def partner_description(index):
    role, aim, history, _ = PARTNER_DETAILS[index]
    return f"{NOTICE}\n\nบทบาท: {role}\n\nเป้าหมายความร่วมมือ: {aim}\n\nประวัติและบริบท: {history}"


def activity_description(index):
    purpose, audience, agenda, result = ACTIVITY_DETAILS[index]
    return f"{NOTICE}\n\nวัตถุประสงค์: {purpose}\n\nกลุ่มเป้าหมาย: {audience}\n\nกำหนดการสมมติ: {agenda}\n\nผลลัพธ์ / งานถัดไป: {result}"
